    await page.goto('/')
    const html = page.locator('html')
    const initialTheme = await html.getAttribute('data-theme')
    await page.keyboard.press('t')
    const newTheme = await html.getAttribute('data-theme')
    expect(newTheme).not.toBe(initialTheme)
  })

  test('error aggregation view has clustered mode', async ({ page }) => {
    await page.goto('/#/errors')
    await expect(page.locator('text=Error Aggregation').or(page.locator('text=All Errors'))).toBeVisible()
    const clusteredBtn = page.locator('button:has-text("Clustered")')
    if (await clusteredBtn.isVisible()) {
      await clusteredBtn.click()
      await expect(page.locator('text=clusters from')).toBeVisible({ timeout: 3000 })
    }
  })
})

/**
 * Search index worker — searches file content for a pattern.
 *
 * Input: { content: string, query: string, filePath: string, regex?: boolean }
 * Output: { results: Array<{ filePath: string, lineNumber: number, lineContent: string, matchStart: number, matchEnd: number }> }
 */

export function handleMessage(data: {
  content: string
  query: string
  filePath: string
  regex?: boolean
}): {
  results: Array<{
    filePath: string
    lineNumber: number
    lineContent: string
    matchStart: number
    matchEnd: number
  }>
} {
  const { content, query, filePath, regex } = data
  const results: Array<{
    filePath: string
    lineNumber: number
    lineContent: string
    matchStart: number
    matchEnd: number
  }> = []

  const lines = content.split('\n')
  const pattern = regex ? new RegExp(query, 'gi') : null

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (regex && pattern) {
      pattern.lastIndex = 0
      const match = pattern.exec(line)
      if (match) {
        results.push({
          filePath,
          lineNumber: i + 1,
          lineContent: line.slice(0, 200),
          matchStart: match.index,
          matchEnd: match.index + match[0].length,
        })
      }
    } else {
      const idx = line.toLowerCase().indexOf(query.toLowerCase())
      if (idx >= 0) {
        results.push({
          filePath,
          lineNumber: i + 1,
          lineContent: line.slice(0, 200),
          matchStart: idx,
          matchEnd: idx + query.length,
        })
      }
    }
  }

  return { results }
}

if (typeof self !== 'undefined' && typeof (self as any).onmessage !== 'undefined') {
  self.onmessage = (event: MessageEvent) => {
    const result = handleMessage(event.data)
    self.postMessage(result)
  }
}

import { defineStore } from 'pinia'

export interface GrepResult {
  filePath: string
  lineNumber: number
  lineContent: string
  matchStart: number
  matchEnd: number
}

export const useSearchStore = defineStore('search', {
  state: () => ({
    grepQuery: '',
    grepRegex: false,
    grepScope: 'all' as 'all' | string, // 'all' or a DUT ID
    grepResults: [] as GrepResult[],
    grepSearching: false,
    grepFilesSearched: 0,
    grepFilesTotal: 0,
    grepPanelOpen: false,
  }),

  actions: {
    addResults(results: GrepResult[]) {
      this.grepResults.push(...results)
    },
    clearResults() {
      this.grepResults = []
      this.grepFilesSearched = 0
    },
    togglePanel() {
      this.grepPanelOpen = !this.grepPanelOpen
    },
  },
})

import { ref, watch } from 'vue'
import { useManifestStore } from '@/stores/manifest'
import type { FileEntry, ErrorEntry } from '@/types/manifest'

export interface SearchResult {
  type: 'file' | 'collector' | 'dut' | 'error'
  label: string
  sublabel: string
  path: string  // route path to navigate to
  score: number
}

export function useSearch() {
  const manifestStore = useManifestStore()
  const query = ref('')
  const results = ref<SearchResult[]>([])

  function search(q: string): SearchResult[] {
    if (!q || q.length < 2) return []
    const lower = q.toLowerCase()
    const matched: SearchResult[] = []

    // Search files
    for (const f of manifestStore.fileIndex) {
      const fileName = f.path.split('/').pop() ?? ''
      const score = fuzzyScore(lower, f.path.toLowerCase())
      if (score > 0) {
        matched.push({
          type: 'file',
          label: fileName,
          sublabel: f.path,
          path: `/file/${encodeURIComponent(f.path)}`,
          score,
        })
      }
    }

    // Search DUTs
    for (const dut of manifestStore.duts) {
      if (dut.id.toLowerCase().includes(lower)) {
        matched.push({
          type: 'dut',
          label: dut.id,
          sublabel: `${dut.baseboard} — ${dut.overall_status}`,
          path: `/dut/${dut.id}`,
          score: 100,
        })
      }
    }

    // Search collectors
    for (const dut of manifestStore.duts) {
      for (const group of dut.collector_groups) {
        for (const c of group.collectors) {
          const text = `${c.id} ${c.name}`.toLowerCase()
          if (text.includes(lower)) {
            matched.push({
              type: 'collector',
              label: `${c.id} — ${c.name}`,
              sublabel: `${dut.id} / ${group.name}`,
              path: `/dut/${dut.id}/${group.name}/${c.id}`,
              score: 80,
            })
          }
        }
      }
    }

    // Search errors
    for (const e of manifestStore.errors) {
      if (e.message.toLowerCase().includes(lower)) {
        matched.push({
          type: 'error',
          label: e.message.slice(0, 80),
          sublabel: `${e.dut_id} / ${e.collector_id}`,
          path: `/dut/${e.dut_id}/${e.collector_group}/${e.collector_id}`,
          score: 60,
        })
      }
    }

    return matched.sort((a, b) => b.score - a.score).slice(0, 50)
  }

  // Simple fuzzy scoring
  function fuzzyScore(query: string, target: string): number {
    if (target.includes(query)) return 100 - target.indexOf(query)
    // Check if all chars appear in order
    let qi = 0
    for (let i = 0; i < target.length && qi < query.length; i++) {
      if (target[i] === query[qi]) qi++
    }
    return qi === query.length ? 50 - query.length : 0
  }

  let debounceTimer: ReturnType<typeof setTimeout>
  watch(query, (q) => {
    clearTimeout(debounceTimer)
    debounceTimer = setTimeout(() => {
      results.value = search(q)
    }, 50)
  })

  return { query, results, search }
}

import { test, expect } from '@playwright/test'

test.describe('Navigation', () => {
  test('hash routing works', async ({ page }) => {
    await page.goto('/#/timing')
    await expect(page.locator('h2')).toContainText(/Timing/i)
  })

  test('breadcrumbs show correct path', async ({ page }) => {
    await page.goto('/#/dut/DUT_1')
    await expect(page.locator('text=Dashboard')).toBeVisible()
    await expect(page.locator('text=DUT_1')).toBeVisible()
  })

  test('file map view loads', async ({ page }) => {
    await page.goto('/#/file-map')
    await expect(page.locator('text=File Map')).toBeVisible()
    await expect(page.locator('text=Total Files')).toBeVisible()
  })

  test('errors view shows error table', async ({ page }) => {
    await page.goto('/#/errors')
    await expect(page.locator('text=Connection timeout')).toBeVisible()
  })

  test('timing view shows charts section', async ({ page }) => {
    await page.goto('/#/timing')
    await expect(page.locator('text=Timing')).toBeVisible()
  })

  test('heatmap view loads', async ({ page }) => {
    await page.goto('/#/heatmap')
    await expect(page.locator('text=Health Heatmap')).toBeVisible()
  })

  test('theme toggle works', async ({ page }) => {
    await page.goto('/')
    const html = page.locator('html')
    const initialTheme = await html.getAttribute('data-theme')
    // Press 't' to toggle
    await page.keyboard.press('t')
    const newTheme = await html.getAttribute('data-theme')
    expect(newTheme).not.toBe(initialTheme)
  })
})

