import { test, expect } from '@playwright/test'

test.describe('File Viewer', () => {
  test('file map shows all files with table view', async ({ page }) => {
    await page.goto('/#/file-map')
    await expect(page.locator('text=File Map')).toBeVisible()
    await expect(page.locator('text=Total Files')).toBeVisible()
  })

  test('file map tree view toggle works', async ({ page }) => {
    await page.goto('/#/file-map')
    await page.locator('button:has-text("Tree")').click()
    await expect(page.locator('.file-tree')).toBeVisible({ timeout: 5000 })
  })

  test('file map DUT filter works', async ({ page }) => {
    await page.goto('/#/file-map')
    const select = page.locator('select').first()
    await select.selectOption({ index: 1 })
    await page.waitForLoadState('networkidle')
  })

  test('file map export CSV works', async ({ page }) => {
    await page.goto('/#/file-map')
    const downloadPromise = page.waitForEvent('download')
    await page.locator('button:has-text("Export CSV")').click()
    const download = await downloadPromise
    expect(download.suggestedFilename()).toContain('nvdebug-files')
    expect(download.suggestedFilename()).toContain('.csv')
  })

  test('file view loads content', async ({ page }) => {
    await page.goto('/#/file-map')
    await page.locator('table tbody tr').first().click()
    await page.waitForURL(/#\/file\//)
    await expect(page.locator('.file-info-bar')).toBeVisible({ timeout: 5000 })
  })

  test('split view accessible via route', async ({ page }) => {
    await page.goto('/#/split')
    await expect(page.locator('text=Side-by-Side')).toBeVisible()
    await expect(page.locator('select')).toHaveCount(2)
  })
})

import { test, expect } from '@playwright/test'

test.describe('Dashboard', () => {
  test('renders stat cards with correct data', async ({ page }) => {
    await page.goto('/')
    await expect(page.locator('text=NVDebug')).toBeVisible()
    // Stat cards should show data from manifest
    await expect(page.locator('text=Total DUTs')).toBeVisible()
    await expect(page.locator('text=1')).toBeVisible() // 1 DUT
  })

  test('shows collection status progress bar', async ({ page }) => {
    await page.goto('/')
    // Progress bar segments should be visible
    await expect(page.locator('text=Collection Status').or(page.locator('text=66.7%'))).toBeVisible({ timeout: 5000 })
  })

  test('DUT table has correct rows', async ({ page }) => {
    await page.goto('/')
    await expect(page.locator('text=DUT_1')).toBeVisible()
  })

  test('navigates to DUT view on row click', async ({ page }) => {
    await page.goto('/')
    await page.locator('text=DUT_1').first().click()
    await expect(page).toHaveURL(/#\/dut\/DUT_1/)
  })

  test('status card navigates to status page', async ({ page }) => {
    await page.goto('/')
    // Click "Failed" stat card
    await page.locator('text=Failed').first().click()
    await expect(page).toHaveURL(/#\/status\/error/)
  })
})

import { test, expect } from '@playwright/test'

test.describe('Performance Budget', () => {
  test.slow()

  test('dashboard renders within budget', async ({ page }) => {
    const start = Date.now()
    await page.goto('/')
    await expect(page.locator('text=NVDebug')).toBeVisible()
    await expect(page.locator('text=Total DUTs')).toBeVisible()
    const elapsed = Date.now() - start
    expect(elapsed).toBeLessThan(5000)
  })

  test('file map renders within budget', async ({ page }) => {
    const start = Date.now()
    await page.goto('/#/file-map')
    await expect(page.locator('text=File Map')).toBeVisible()
    const elapsed = Date.now() - start
    expect(elapsed).toBeLessThan(5000)
  })

  test('timing view renders within budget', async ({ page }) => {
    const start = Date.now()
    await page.goto('/#/timing')
    await expect(page.locator('text=Timing Analysis')).toBeVisible()
    const elapsed = Date.now() - start
    expect(elapsed).toBeLessThan(6000)
  })

  test('error aggregation renders within budget', async ({ page }) => {
    const start = Date.now()
    await page.goto('/#/errors')
    await expect(page.locator('text=Errors').first()).toBeVisible()
    const elapsed = Date.now() - start
    expect(elapsed).toBeLessThan(5000)
  })

  test('theme toggle is fast', async ({ page }) => {
    await page.goto('/')
    await expect(page.locator('text=NVDebug')).toBeVisible()
    const html = page.locator('html')
    const before = await html.getAttribute('data-theme')
    await page.keyboard.press('t')
    await expect(html).not.toHaveAttribute('data-theme', before ?? '')
  })
})

