      { id: 'R37', name: 'GPU Debug Dump', group: 'redfish', dutId: 'DUT_A', duration: 240 },
      { id: 'H2', name: 'Host Logs', group: 'host', dutId: 'DUT_B', duration: 40 },
      { id: 'R1', name: 'Inventory', group: 'redfish', dutId: 'DUT_A', duration: 8 },
